import{_ as o,o as c,c as d,a2 as i}from"./chunks/framework.CuUVWMxs.js";const p=JSON.parse('{"title":"后端 API 规范","description":"","frontmatter":{},"headers":[],"relativePath":"mango-pmo/rules/backend/03-api.md","filePath":"mango-pmo/rules/backend/03-api.md"}'),r={name:"mango-pmo/rules/backend/03-api.md"};function a(t,e,l,n,A,C){return c(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="后端-api-规范" tabindex="-1">后端 API 规范 <a class="header-anchor" href="#后端-api-规范" aria-label="Permalink to &quot;后端 API 规范&quot;">​</a></h1><h2 id="_1-基本规则" tabindex="-1">1. 基本规则 <a class="header-anchor" href="#_1-基本规则" aria-label="Permalink to &quot;1. 基本规则&quot;">​</a></h2><ul><li>API 只暴露协议模型。</li><li>不暴露 <code>Entity</code>、<code>PO</code>。</li><li>写操作使用 <code>Command</code>。</li><li>查询使用 <code>Query</code>。</li><li>返回统一使用 <code>VO</code>。</li></ul><h2 id="_2-入参规则" tabindex="-1">2. 入参规则 <a class="header-anchor" href="#_2-入参规则" aria-label="Permalink to &quot;2. 入参规则&quot;">​</a></h2><ul><li>创建使用 <code>CreateXxxCommand</code>。</li><li>更新使用 <code>UpdateXxxCommand</code>。</li><li>查询使用 <code>XxxQuery</code> 或 <code>XxxPageQuery</code>。</li><li>新增 API 禁止路径变量和 URI 模板；简单标识统一使用 <code>@RequestParam</code>，请求头使用 <code>@RequestHeader</code>。</li><li>1-2 个简单查询参数可以直接放方法签名；路径中不得出现 <code>{id}</code>、<code>{code}</code> 等变量段。</li><li>客户端可传入参数超过 2 个时必须收敛为 <code>Command</code>、<code>Query</code> 或专用请求对象；<code>HttpServletRequest</code>、<code>HttpServletResponse</code> 等服务端上下文对象不计入客户端入参数量。</li><li><code>GET</code> 禁止使用 <code>@RequestBody</code>；复杂 <code>Query</code> 对象必须使用 <code>@ParameterObject</code> 展开为 query 参数，禁止在 OpenAPI/Knife4j 中显示为 <code>query={...}</code> JSON 字符串参数。</li><li><code>POST</code> / <code>PUT</code> / <code>PATCH</code> 的 <code>Command</code>、<code>Request</code> 默认使用必填 <code>@RequestBody</code> 接收 JSON；只有明确声明为表单提交的接口才允许使用 <code>@RequestParam</code> / <code>@ModelAttribute</code>。</li><li><code>DELETE</code> 的简单标识优先使用 <code>@RequestParam</code>；批量删除等复杂命令使用 <code>@RequestBody</code>。</li><li>API 参数必须使用 Bean Validation 校验。</li><li><code>Command</code>、<code>Query</code> 字段必须声明 <code>jakarta.validation</code> 约束注解。</li><li>协议模型使用普通 class；禁止用 record 作为 Command/Query/Request/VO/Response，禁止继承非协议模型基类。</li><li>嵌套 Command/Query/Request 字段必须使用 <code>@Valid</code> 级联校验；字段类型只能是标量、枚举、同类协议模型及受支持的单泛型容器。</li><li>查询参数必须声明校验约束。</li><li>Controller 或 <code>Api</code> 必须使用 <code>@Validated</code> 或等效机制开启参数校验。</li></ul><h2 id="_2-1-service-入参规则" tabindex="-1">2.1 Service 入参规则 <a class="header-anchor" href="#_2-1-service-入参规则" aria-label="Permalink to &quot;2.1 Service 入参规则&quot;">​</a></h2><ul><li><code>XxxApi</code>、Controller、<code>IXxxService</code> 和 <code>XxxService</code> 的核心业务方法必须保持同一入参模型。</li><li>创建、更新、查询、批量操作和复杂业务动作必须使用 <code>Command</code>、<code>Query</code> 或专用请求对象。</li><li>Service 方法超过 2 个业务字段入参时，必须收敛为 <code>Command</code>、<code>Query</code> 或专用请求对象。</li><li>允许直接展开的参数仅限 <code>id</code>、状态枚举、布尔控制位等 1-2 个简单控制参数。</li><li>Controller 调 Service 时直接传 <code>Command</code>、<code>Query</code> 或专用请求对象；Service 负责校验后的业务编排和模型转换。</li><li>Service 调 Mapper 时不得继续传 API 协议模型，必须转换为 Entity、id、Wrapper、分页对象或 core 内部持久化查询对象。</li></ul><h2 id="_2-2-文件字段规则" tabindex="-1">2.2 文件字段规则 <a class="header-anchor" href="#_2-2-文件字段规则" aria-label="Permalink to &quot;2.2 文件字段规则&quot;">​</a></h2><ul><li>业务 API 的创建、更新入参禁止接收需要持久化的文件访问地址字段，例如 <code>url</code>、<code>previewUrl</code>、<code>downloadUrl</code>、<code>directPreviewUrl</code>、<code>directDownloadUrl</code>。</li><li>业务 API 应接收文件中心标识字段，例如 <code>fileId</code>、<code>fileIds</code>、<code>attachmentIds</code>、<code>iconFileId</code>，或明确的 <code>mango-file:{id}</code> token。</li><li>业务 VO 可以返回文件 ID；如页面需要临时预览或下载地址，由前端通过 <code>mango-file</code> 查询，或由业务聚合层在响应时临时组装，禁止反写到业务表。</li><li>预签名 URL、对象存储直连地址只允许作为单次响应中的运行时字段，不允许成为业务 Command、Entity 或持久化 JSON 的字段。</li></ul><h2 id="_2-3-openapi-knife4j-文档规则" tabindex="-1">2.3 OpenAPI / Knife4j 文档规则 <a class="header-anchor" href="#_2-3-openapi-knife4j-文档规则" aria-label="Permalink to &quot;2.3 OpenAPI / Knife4j 文档规则&quot;">​</a></h2><ul><li>所有对外展示的 Controller 必须声明中文 <code>@Tag(name, description)</code>，禁止显示默认的 <code>xxx-controller</code>。</li><li>所有 HTTP 接口方法必须声明中文 <code>@Operation(summary, description)</code>；<code>summary</code> 说明接口动作，<code>description</code> 说明业务语义、访问边界或关键约束。</li><li>所有客户端可传入参数都必须在文档中展示中文含义。</li><li>所有简单请求参数必须声明中文 <code>@Parameter(description = &quot;...&quot;)</code>，包括 <code>@RequestParam</code>、<code>@RequestHeader</code>、<code>@PathVariable</code>（路径变量本身禁止新增）。</li><li>所有 <code>Command</code>、<code>Query</code>、<code>Request</code>、<code>Response</code>、<code>VO</code>、<code>PO</code>、<code>DTO</code> 字段必须声明中文 <code>@Schema(description = &quot;...&quot;)</code>；字段含义、枚举值或取值约束要能在文档中直接看懂。</li><li><code>GET</code> Query 对象在 Controller 方法参数上必须使用 <code>@ParameterObject</code>，并依赖字段级 <code>@Schema</code> 展示中文参数含义。</li><li><code>POST</code> / <code>PUT</code> JSON body 的 Controller 参数必须使用 <code>@RequestBody</code>，并依赖请求对象字段级 <code>@Schema</code> 展示中文字段含义。</li><li>鉴权文档使用名为 <code>Authorization</code> 的 header apiKey 安全方案；Knife4j 调试时输入完整 <code>Bearer &lt;accessToken&gt;</code>，请求必须发出标准 <code>Authorization</code> 请求头。</li><li>内部接口可以在 <code>@Operation(description)</code> 中说明“仅内部调用”；是否显示对内 tag 由文档配置控制，不允许为了文档展示修改真实访问权限。</li></ul><h2 id="_3-返回规则" tabindex="-1">3. 返回规则 <a class="header-anchor" href="#_3-返回规则" aria-label="Permalink to &quot;3. 返回规则&quot;">​</a></h2><ul><li>无数据成功：<code>R&lt;Void&gt;</code></li><li>单对象：<code>R&lt;XxxVO&gt;</code></li><li>列表：<code>R&lt;List&lt;XxxVO&gt;&gt;</code></li><li>分页：<code>R&lt;PageResult&lt;XxxVO&gt;&gt;</code></li><li>简单状态：<code>R&lt;Boolean&gt;</code></li><li>简单标识：<code>R&lt;Long&gt;</code>、<code>R&lt;String&gt;</code></li></ul><h2 id="_3-1-数据来源规则" tabindex="-1">3.1 数据来源规则 <a class="header-anchor" href="#_3-1-数据来源规则" aria-label="Permalink to &quot;3.1 数据来源规则&quot;">​</a></h2><ul><li>API 返回的数据必须来自数据库、配置、枚举契约、字典服务、远程 API 或明确的运行时计算。</li><li>本应由数据库维护的数据，禁止在 Controller、Service、Converter 或 VO 组装逻辑中写死。</li><li>菜单、权限、公共路径、租户默认数据、字典、业务状态、流程配置、计费规则等可运营数据必须有数据库、migration、配置中心或后台维护入口。</li><li>临时调试数据和 mock 数据禁止进入最终 API 实现。</li><li>接口尚未接入真实数据源时，必须标记为未完成或阻塞，禁止声明可供前端替换 mock。</li></ul><h2 id="_4-分层规则" tabindex="-1">4. 分层规则 <a class="header-anchor" href="#_4-分层规则" aria-label="Permalink to &quot;4. 分层规则&quot;">​</a></h2><ul><li><code>api</code> 只放 <code>XxxApi</code>、<code>command</code>、<code>query</code>、<code>vo</code>、<code>enums</code>。</li><li><code>api</code> 如需声明内部访问边界，允许依赖 <code>mango-infra-web-api</code> 并在 <code>XxxApi</code> 类或方法上使用 <code>@Inner</code>。</li><li><code>api</code> 禁止依赖 <code>mango-infra-web-starter</code>。</li><li>Controller 只做协议适配。</li><li>Controller 必须实现对应 <code>XxxApi</code>，内部只能依赖 <code>IXxxService</code> 或等效服务接口。</li><li>Controller 禁止持有 <code>XxxApi</code> 字段进行自调用。</li><li>Controller 不直接操作 <code>Mapper</code>。</li><li>Controller 不直接返回持久化对象。</li><li><code>XxxApi</code> 只定义能力契约。</li><li><code>XxxApi</code> 保持传输无关，只声明 Java 方法、Bean Validation 和 <code>R&lt;T&gt;</code>；禁止声明 Spring MVC mapping、<code>@RequestBody</code>、<code>@RequestParam</code>、<code>@RequestHeader</code> 或 <code>@PathVariable</code>。</li><li><code>XxxApi</code> 不继承其它接口，不声明字段、常量、default/static/private 方法；完整契约直接声明在本接口。</li><li><code>XxxApi</code> 禁止声明 <code>@FeignClient</code>。</li><li><code>XxxService</code> 禁止直接实现 <code>XxxApi</code>；服务层应实现 <code>IXxxService</code>。</li><li><code>XxxController</code> 和 <code>XxxFeignClient</code> 分别实现同一个 <code>XxxApi</code>，只在各自适配层重声明 HTTP 注解；不得在三处发明不同方法签名。</li></ul><h2 id="_4-1-controller、service-与错误契约" tabindex="-1">4.1 Controller、Service 与错误契约 <a class="header-anchor" href="#_4-1-controller、service-与错误契约" aria-label="Permalink to &quot;4.1 Controller、Service 与错误契约&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>必须负责</th><th>绝对禁止</th></tr></thead><tbody><tr><td><code>XxxApi</code></td><td>传输无关的协议方法、Command/Query/VO、校验约束、统一 <code>R&lt;T&gt;</code> 返回</td><td>Entity/PO、Spring MVC/Feign 注解、实现逻辑、裸返回值</td></tr><tr><td><code>XxxController</code></td><td>直接声明 <code>@RestController</code>，实现唯一一个 <code>XxxApi</code>、协议适配、<code>@Validated</code>、必填 <code>@RequestBody @Valid</code>、调用 <code>IXxxService</code>、直接返回 <code>R.ok(service.xxx(...))</code></td><td>继承 Controller 基类，Mapper/Entity/Feign/具体 Service 依赖，硬编码返回值，自行拼装失败 <code>R</code>，业务判断和持久化</td></tr><tr><td><code>IXxxService</code>/实现</td><td>业务编排、业务前置条件、Command/Query 到持久化模型转换、事务和状态结果</td><td>返回或拼装 <code>R</code>，直接实现 <code>XxxApi</code>，用 <code>if/throw</code>、裸异常或静默 return 代替 <code>Require</code></td></tr><tr><td><code>XxxMapper</code></td><td>Entity/id/Wrapper/分页及 core 内部 <code>Criteria</code>/<code>Row</code> 等类型化持久化模型的数据访问</td><td><code>Object</code>、<code>Map</code>、Command/Query/Request/Response/VO/DTO、Controller/Feign/Service/传输上下文、注解 SQL、跨域表访问</td></tr></tbody></table><ul><li>Controller 的基础字段校验由 Bean Validation 完成；业务存在性、状态、归属、权限、重复和前后置条件必须在 Service 使用 <code>Require</code> 校验。</li><li>Service 的业务失败必须使用模块 <code>XxxCode implements BizCode</code>（即统一 ErrorCode 契约）；禁止裸数字错误码和临时错误字符串作为新增业务错误契约。</li><li>Controller 只返回成功 <code>R&lt;T&gt;</code>；业务失败由 Service 抛出带 <code>BizCode</code> 的业务异常，再由统一异常处理器转换为失败 <code>R&lt;T&gt;</code>。</li><li>Service 实现类统一命名 <code>XxxService implements IXxxService</code>；禁止新增 <code>XxxServiceImpl</code>。</li><li><code>IXxxService</code> 只位于 <code>core</code>，只允许继承 canonical <code>MangoCrudService</code> / <code>MangoTypedCrudService</code>；实现类除 canonical <code>MangoCrudServiceImpl</code> 外不得继承业务基类或 MyBatis <code>ServiceImpl</code>。</li><li>以上为不可降级结构红线：新增文件或被修改文件命中时，即使历史基线存在也必须失败，不允许普通例外。</li></ul><h2 id="_4-2-spring-service-注册与对象创建" tabindex="-1">4.2 Spring Service 注册与对象创建 <a class="header-anchor" href="#_4-2-spring-service-注册与对象创建" aria-label="Permalink to &quot;4.2 Spring Service 注册与对象创建&quot;">​</a></h2><h3 id="_4-2-1-业务-service" tabindex="-1">4.2.1 业务 Service <a class="header-anchor" href="#_4-2-1-业务-service" aria-label="Permalink to &quot;4.2.1 业务 Service&quot;">​</a></h3><ul><li><strong>正向要求</strong>：<code>core</code> 业务实现使用 <code>XxxService implements IXxxService</code>，并直接声明 <code>@Service</code>；Controller 和其它业务 Service 通过构造器注入 <code>IXxxService</code>，事务、异步、缓存和调度注解只能出现在已证明由 Spring 托管的对象上。</li><li><strong>禁止项</strong>：禁止业务实现遗漏 <code>@Service</code>；禁止用 <code>@Component</code>、starter <code>@Bean</code>、静态字段或 Service Locator 规避业务 Service 约定；禁止 Controller 或业务 Service 执行 <code>new XxxService(...)</code>。</li><li><strong>正例</strong>：<code>@Service public class OrderService implements IOrderService</code>，Controller 构造器接收 <code>IOrderService</code>，<code>@Transactional</code> 方法由 Spring 代理调用。</li><li><strong>反例</strong>：<code>OrderController</code> 内执行 <code>new OrderService(mapper)</code>。错误原因：绕过依赖注入、事务代理、缓存、异步、生命周期和业务项目覆盖能力。</li></ul><h3 id="_4-2-2-starter-默认实现与框架-spi" tabindex="-1">4.2.2 starter 默认实现与框架 SPI <a class="header-anchor" href="#_4-2-2-starter-默认实现与框架-spi" aria-label="Permalink to &quot;4.2.2 starter 默认实现与框架 SPI&quot;">​</a></h3><ul><li><strong>正向要求</strong>：框架 SPI、默认适配器或可被业务项目替换的实现可以保持普通 Java 类，但必须由拥有运行时装配责任的 starter 通过 <code>@Bean + @ConditionalOnMissingBean</code> 注册；实现类与 starter 可以跨模块，机器门禁以完整 Reactor 证明注册关系。</li><li><strong>禁止项</strong>：禁止同时给同一实现声明 <code>@Service</code> 和 <code>@Bean</code>；禁止默认实现只写 <code>@Bean</code> 而缺少 <code>@ConditionalOnMissingBean</code>；禁止把注册逻辑放进 Controller 或业务 Service。</li><li><strong>正例</strong>：<code>SystemEventService</code> 不声明 stereotype，<code>DomainEventAutoConfiguration</code> 使用 <code>@Bean @ConditionalOnMissingBean</code> 返回该对象，业务项目可提供同类型 Bean 覆盖默认实现。</li><li><strong>反例</strong>：默认加密实现既声明 <code>@Service</code>，starter 又无条件 <code>@Bean</code> 构造一次。错误原因：存在重复 Bean、覆盖失效和运行时装配歧义。</li></ul><h3 id="_4-2-3-纯-java-对象与静态状态" tabindex="-1">4.2.3 纯 Java 对象与静态状态 <a class="header-anchor" href="#_4-2-3-纯-java-对象与静态状态" aria-label="Permalink to &quot;4.2.3 纯 Java 对象与静态状态&quot;">​</a></h3><ul><li><strong>正向要求</strong>：无事务、异步、缓存、调度、注入和生命周期需求的算法、策略、codec、factory、calculator 可以由调用方显式创建；名称必须表达纯对象职责，不使用 <code>Service</code> 冒充容器服务。</li><li><strong>禁止项</strong>：禁止可变 static 字段保存 <code>I*Service</code> 或 <code>*Service</code>；禁止新增静态 <code>getService/setService</code> 桥接容器；禁止在未注册对象上声明 <code>@Transactional</code>、<code>@Async</code>、<code>@Scheduled</code>、<code>@Cacheable</code>、<code>@CacheEvict</code> 或 <code>@CachePut</code>。</li><li><strong>正例</strong>：<code>MoneyCalculator calculator = new MoneyCalculator(roundingPolicy)</code>，对象无 Spring 注解、无容器依赖且不命名为 Service。</li><li><strong>反例</strong>：<code>private static volatile IOrderService current</code> 配合静态 setter。错误原因：形成隐式全局依赖，测试隔离、并发可见性、生命周期和多上下文行为不可证明。</li></ul><h2 id="_4-3-remote-adapter-规则" tabindex="-1">4.3 Remote Adapter 规则 <a class="header-anchor" href="#_4-3-remote-adapter-规则" aria-label="Permalink to &quot;4.3 Remote Adapter 规则&quot;">​</a></h2><ul><li><code>XxxFeignClient</code> 只能位于 <code>starter-remote</code>，必须且仅能继承一个本域 <code>XxxApi</code>。</li><li><code>@FeignClient</code> 必须显式声明与模块信息一致的 <code>name</code>、唯一的 lowerCamelCase <code>contextId</code> 和以模块 <code>module-path</code> 开头的绝对 <code>path</code>。</li><li>Controller 根路径和 Feign path 必须是静态字面量，禁止 <code>${...}</code>、<code>#{...}</code>、URI 模板和多路径/条件 mapping。</li><li>Feign 只重声明继承方法所需的 mapping、body/query/header 注解，不定义新业务能力、不持有 Mapper/Entity/Service、不包含业务判断。</li><li>Controller 根路径与 Feign <code>path</code> 必须表达同一模块和资源根；方法级 mapping 必须逐一一致。</li><li>正例：<code>OrderFeignClient extends OrderApi</code>，<code>name = &quot;order&quot;</code>、<code>contextId = &quot;orderFeignClient&quot;</code>、<code>path = &quot;/order/orders&quot;</code>，方法使用 <code>@GetMapping(&quot;/detail&quot;) + @RequestParam(&quot;id&quot;)</code>。</li><li>反例：Feign 放进 <code>api</code>；继承两个 API；缺 <code>contextId</code>；Controller 使用 <code>/detail?id=</code> 而 Feign 使用 <code>/detail/{id}</code>；在 Feign 内增加 API 不存在的方法。</li></ul><h2 id="_5-dto-规则" tabindex="-1">5. DTO 规则 <a class="header-anchor" href="#_5-dto-规则" aria-label="Permalink to &quot;5. DTO 规则&quot;">​</a></h2><ul><li>仓内业务 API 禁止使用 <code>DTO</code> 作为默认入参或返回命名。</li><li><code>DTO</code> 只允许用于第三方集成、外部回调、历史兼容层。</li></ul><h2 id="_6-兼容策略" tabindex="-1">6. 兼容策略 <a class="header-anchor" href="#_6-兼容策略" aria-label="Permalink to &quot;6. 兼容策略&quot;">​</a></h2><ul><li>新增接口必须遵守本规范。</li><li>老接口按模块逐步迁移。</li><li>迁移期间允许在 service 或 convert 层做兼容转换。</li><li>不允许继续新增 <code>DTO</code>、<code>PO</code>、<code>Entity</code> 直出直入接口。</li></ul><h2 id="_7-禁止事项" tabindex="-1">7. 禁止事项 <a class="header-anchor" href="#_7-禁止事项" aria-label="Permalink to &quot;7. 禁止事项&quot;">​</a></h2><ul><li><code>@RequestBody XxxEntity</code></li><li><code>@PathVariable</code> 或 mapping 路径中的 <code>{variable}</code></li><li><code>R&lt;XxxEntity&gt;</code></li><li><code>R&lt;PageResult&lt;XxxEntity&gt;&gt;</code></li><li><code>UserDTO</code> 作为仓内业务 API 返回</li><li><code>Map&lt;String, Object&gt;</code> 作为通用业务接口模型</li><li>无校验注解的 <code>Command</code> / <code>Query</code></li><li>API 参数绕过 Bean Validation 直接进入业务层</li><li>在 <code>*-api</code> 中写 <code>@FeignClient</code></li><li>在 API 契约中硬编码服务发现名</li><li>业务 API 用文件访问地址代替文件 ID</li><li>API 写死本应来自数据库、配置、字典服务或真实接口的数据</li><li>Controller 缺少 <code>@Validated</code> 或 <code>@RequestBody</code> 缺少 <code>@Valid</code></li><li>Controller 未实现 <code>XxxApi</code>，或依赖 Mapper、Entity、FeignClient、具体 <code>XxxService</code></li><li>Controller/API HTTP 方法不返回 <code>R&lt;T&gt;</code>，或返回 Entity/PO</li><li>Service 返回 <code>R&lt;T&gt;</code>、调用 <code>R.ok/R.fail</code>、直接抛裸运行时/业务异常</li><li>Service 业务动作没有使用 <code>Require + XxxCode implements BizCode</code> 执行业务前置条件校验</li><li>业务 <code>XxxService implements IXxxService</code> 缺少 <code>@Service</code>，或 Controller/业务 Service 手工 <code>new</code> Spring Service</li><li>starter 默认实现缺少 <code>@Bean + @ConditionalOnMissingBean</code>，或同一 Service 同时使用 stereotype 与 <code>@Bean</code></li><li>未注册对象使用事务、异步、缓存、调度注解，或通过可变 static Service 字段实现 Service Locator</li></ul><h2 id="_8-机器门禁" tabindex="-1">8. 机器门禁 <a class="header-anchor" href="#_8-机器门禁" aria-label="Permalink to &quot;8. 机器门禁&quot;">​</a></h2><p>以下 ID 与 <code>MangoJavaArchitectureRule</code>、<code>MangoArchUnitChecker</code>、<code>MavenDependencyChecker</code>、<code>ArchitectureMojo</code> 和 <code>CheckMojo</code> 当前实现逐项对应。禁止用区间概述代替具体 ID。</p><h3 id="_8-1-api、路径、http-与协议模型" tabindex="-1">8.1 API、路径、HTTP 与协议模型 <a class="header-anchor" href="#_8-1-api、路径、http-与协议模型" aria-label="Permalink to &quot;8.1 API、路径、HTTP 与协议模型&quot;">​</a></h3><ul><li><code>MANGO-ARCH-PATH-001</code>：禁止 <code>@PathVariable</code>；<code>MANGO-ARCH-PATH-002</code>：禁止 mapping 字面量中的 URI 模板；<code>MANGO-ARCH-PATH-003</code>：禁止 HTTP 路径使用 <code>${...}</code> 或 <code>#{...}</code> 运行时占位。</li><li><code>MANGO-ARCH-API-001</code>：Api 传输无关；<code>MANGO-ARCH-API-002</code>：复合入参 <code>@Valid</code>、简单入参 Jakarta constraint；<code>MANGO-ARCH-API-003</code>：禁止服务端 transport context；<code>MANGO-ARCH-API-004</code>：客户端入参最多两个；<code>MANGO-ARCH-API-005</code>：禁止字段、常量和方法实现；<code>MANGO-ARCH-API-006</code>：入参只允许标量、枚举、Command、Query、Request；<code>MANGO-ARCH-API-007</code>：Api 不继承其它接口。</li><li><code>MANGO-ARCH-HTTP-001</code>：必须返回参数化 <code>R&lt;T&gt;</code>；<code>MANGO-ARCH-HTTP-002</code>：返回禁止 Entity/PO；<code>MANGO-ARCH-HTTP-003</code>：Api 禁止 Feign 且入参禁止 Entity/PO；<code>MANGO-ARCH-HTTP-004</code>：禁止 raw R；<code>MANGO-ARCH-HTTP-005</code>：禁止 <code>Map&lt;String,Object&gt;</code>；<code>MANGO-ARCH-HTTP-006</code>：入参与返回禁止 DTO；<code>MANGO-ARCH-HTTP-007</code>：R payload 只允许标量、枚举、VO、Response、集合或 PageResult。</li><li><code>MANGO-ARCH-MODEL-001</code>：字段要求非空中文 Schema；<code>MANGO-ARCH-MODEL-002</code>：输入字段要求 Jakarta constraint；<code>MANGO-ARCH-MODEL-003</code>：禁止协议 record；<code>MANGO-ARCH-MODEL-004</code>：输入字段类型白名单；<code>MANGO-ARCH-MODEL-005</code>：输出字段类型白名单；<code>MANGO-ARCH-MODEL-006</code>：只允许同类协议模型继承和 Serializable；<code>MANGO-ARCH-MODEL-007</code>：嵌套输入要求 <code>@Valid</code>。</li><li><code>MANGO-ARCH-OPENAPI-001</code>：Controller 要求 Tag；<code>MANGO-ARCH-OPENAPI-002</code>：HTTP 方法要求 Operation；<code>MANGO-ARCH-OPENAPI-003</code>：简单参数要求 Parameter；<code>MANGO-ARCH-OPENAPI-004</code>：Query 要求 ParameterObject；<code>MANGO-ARCH-OPENAPI-005</code>：Tag name/description 要求非空中文；<code>MANGO-ARCH-OPENAPI-006</code>：Operation summary/description 要求非空中文；<code>MANGO-ARCH-OPENAPI-007</code>：Parameter description 要求非空中文。</li></ul><h3 id="_8-2-类型位置与-controller" tabindex="-1">8.2 类型位置与 Controller <a class="header-anchor" href="#_8-2-类型位置与-controller" aria-label="Permalink to &quot;8.2 类型位置与 Controller&quot;">​</a></h3><ul><li><code>MANGO-ARCH-TYPE-001</code>：Controller 位于 starter；<code>MANGO-ARCH-TYPE-002</code>：Controller 直接且只实现一个本域 Api；<code>MANGO-ARCH-TYPE-003</code>：字段只能是非 static 的 <code>I*Service</code>；<code>MANGO-ARCH-TYPE-004</code>：Service 实现位于 core；<code>MANGO-ARCH-TYPE-005</code>：<code>XxxService</code> 实现 <code>IXxxService</code>；<code>MANGO-ARCH-TYPE-006</code>：Mapper 位于 core；<code>MANGO-ARCH-TYPE-007</code>：业务 Entity 位于 core；<code>MANGO-ARCH-TYPE-008</code>：Service 禁止实现 HTTP API；<code>MANGO-ARCH-TYPE-009</code>：Api 位于 api；<code>MANGO-ARCH-TYPE-010</code>：业务 api 只允许契约类型，<code>io.mango.infra.persistence.api</code> 作为 canonical 持久化类型系统可提供基础抽象和不可变值类型；<code>MANGO-ARCH-TYPE-011</code>：<code>IXxxService</code> 位于 core。</li><li><code>MANGO-ARCH-CTRL-001</code>：要求 <code>@Validated</code>；<code>MANGO-ARCH-CTRL-002</code>：源码字段只依赖 <code>I*Service</code>；<code>MANGO-ARCH-CTRL-003</code>：body 要求 <code>@Valid</code>；<code>MANGO-ARCH-CTRL-004</code>：只允许直接返回 canonical <code>R.ok(...)</code>；<code>MANGO-ARCH-CTRL-005</code>：逐项重声明 Api mapping、保留精确泛型且禁止 Api 外方法；<code>MANGO-ARCH-CTRL-006</code>：GET 禁止 body；<code>MANGO-ARCH-CTRL-007</code>：写 Command/Request 使用 required body；<code>MANGO-ARCH-CTRL-008</code>：唯一根路径匹配 module-path；<code>MANGO-ARCH-CTRL-009</code>：禁止 Controller 继承；<code>MANGO-ARCH-CTRL-010</code>：禁止 throw；<code>MANGO-ARCH-CTRL-011</code>：直接声明 canonical RestController；<code>MANGO-ARCH-CTRL-012</code>：根 mapping 只能一个 path 且无 method/params/headers/consumes/produces 条件；<code>MANGO-ARCH-CTRL-013</code>：<code>R.ok</code> 必须包装 <code>I*Service</code> 调用结果，禁止硬编码 payload。</li></ul><h3 id="_8-3-service、mapper-与-entity" tabindex="-1">8.3 Service、Mapper 与 Entity <a class="header-anchor" href="#_8-3-service、mapper-与-entity" aria-label="Permalink to &quot;8.3 Service、Mapper 与 Entity&quot;">​</a></h3><ul><li><code>MANGO-ARCH-SVC-001</code>：Service 禁止返回 R；<code>MANGO-ARCH-SVC-002</code>：禁止调用或构造 R；<code>MANGO-ARCH-SVC-003</code>：Require 使用模块 <code>XxxCode implements BizCode</code>；<code>MANGO-ARCH-SVC-004</code>：写业务动作要求 Require；<code>MANGO-ARCH-SVC-005</code>：实现类命名 <code>XxxService</code>；<code>MANGO-ARCH-SVC-006</code>：禁止直接 throw；<code>MANGO-ARCH-SVC-007</code>：CRUD 继承 canonical <code>MangoCrudServiceImpl</code>；<code>MANGO-ARCH-SVC-008</code>：CRUD 实现 <code>MangoTypedCrudService</code>；<code>MANGO-ARCH-SVC-009</code>：禁止同名伪造 Mango CRUD 类型；<code>MANGO-ARCH-SVC-010</code>：公共方法最多两个业务入参；<code>MANGO-ARCH-SVC-011</code>：Typed CRUD 六类泛型与 Mapper/Entity 聚合对齐；<code>MANGO-ARCH-SVC-012</code>：Service interface 只声明 abstract 契约；<code>MANGO-ARCH-SVC-013</code>：Service interface 传输无关；<code>MANGO-ARCH-SVC-014</code>：禁止直接继承 MyBatis ServiceImpl；<code>MANGO-ARCH-SVC-015</code>：只允许直接继承 canonical MangoCrudServiceImpl，否则直接继承 Object；<code>MANGO-ARCH-SVC-016</code>：<code>IXxxService</code> 只继承 canonical Mango CRUD contract。</li><li><code>MANGO-ARCH-BEAN-001</code>：业务 <code>IXxxService</code> 实现要求 <code>@Service</code>；<code>MANGO-ARCH-BEAN-002</code>：普通框架 <code>XxxService</code> 要求 starter <code>@Bean + @ConditionalOnMissingBean</code>；<code>MANGO-ARCH-BEAN-003</code>：禁止 <code>@Service</code> 与 <code>@Bean</code> 双重注册；<code>MANGO-ARCH-BEAN-004</code>：Controller/业务 Service 禁止直接构造托管 Service；<code>MANGO-ARCH-BEAN-005</code>：事务、异步、调度和缓存注解要求 Spring Bean 注册证明；<code>MANGO-ARCH-BEAN-006</code>：禁止可变 static Service Locator。</li><li><code>MANGO-ARCH-MAPPER-001</code>：禁止注解/Provider SQL；<code>MANGO-ARCH-MAPPER-002</code>：入参禁止 API model；<code>MANGO-ARCH-MAPPER-003</code>：返回禁止 API model；<code>MANGO-ARCH-MAPPER-004</code>：必须是 <code>@Mapper</code> interface；<code>MANGO-ARCH-MAPPER-005</code>：直接继承 <code>BaseMapper&lt;XxxEntity&gt;</code>；<code>MANGO-ARCH-MAPPER-006</code>：Mapper/Entity 聚合名一致；<code>MANGO-ARCH-MAPPER-007</code>：入参与返回禁止 Object、Map、transport、Controller、FeignClient、Service 等非类型化边界。</li><li><code>MANGO-ARCH-ENTITY-001</code>：持久化类命名 <code>XxxEntity</code>；<code>MANGO-ARCH-ENTITY-002</code>：要求非空 <code>@TableName</code>；<code>MANGO-ARCH-ENTITY-003</code>：普通 Entity 继承 canonical <code>TenantEntity</code>；<code>MANGO-ARCH-ENTITY-004</code>：全局 Entity manifest 表名与 <code>@TableName</code> 一致。</li></ul><h3 id="_8-4-feign、adapter-与模块依赖" tabindex="-1">8.4 Feign、Adapter 与模块依赖 <a class="header-anchor" href="#_8-4-feign、adapter-与模块依赖" aria-label="Permalink to &quot;8.4 Feign、Adapter 与模块依赖&quot;">​</a></h3><ul><li><code>MANGO-ARCH-FEIGN-001</code>：Feign 只位于 starter-remote；<code>MANGO-ARCH-FEIGN-002</code>：直接且只继承一个 Api；<code>MANGO-ARCH-FEIGN-003</code>：name/contextId 非空；<code>MANGO-ARCH-FEIGN-004</code>：path 为绝对路径；<code>MANGO-ARCH-FEIGN-005</code>：contextId 唯一；<code>MANGO-ARCH-FEIGN-006</code>：contextId 等于接口名 lowerCamelCase；<code>MANGO-ARCH-FEIGN-007</code>：name/path 匹配 module.properties；<code>MANGO-ARCH-FEIGN-008</code>：逐项重声明 Api mapping、保留泛型且禁止 Api 外方法；<code>MANGO-ARCH-FEIGN-009</code>：禁止字段/常量，方法保持 abstract。</li><li><code>MANGO-ARCH-ADAPTER-001</code>：Controller/Feign 的 verb、完整 path、参数绑定一致；<code>MANGO-ARCH-ADAPTER-002</code>：每个参数恰有一个显式 binding，query/header 显式命名；<code>MANGO-ARCH-ADAPTER-003</code>：恰有一个 verb、最多一个 path；<code>MANGO-ARCH-ADAPTER-004</code>：方法使用具体 verb annotation，禁止方法级 RequestMapping；<code>MANGO-ARCH-ADAPTER-005</code>：Command/Request body 必填；<code>MANGO-ARCH-ADAPTER-006</code>：禁止 mapping 条件；<code>MANGO-ARCH-ADAPTER-007</code>：verb/model/binding 兼容，Controller Query 用 ParameterObject/ModelAttribute，Feign Query 用 SpringQueryMap。</li><li><code>MANGO-ARCH-DEP-001</code>：api 禁止依赖 core/support/starter；<code>MANGO-ARCH-DEP-002</code>：core 禁止依赖 core/starter；<code>MANGO-ARCH-DEP-003</code>：starter-remote 只依赖本域 api/support 和 infra-feign；<code>MANGO-ARCH-DEP-004</code>：starter-remote 禁止直依赖 OpenFeign starter；<code>MANGO-ARCH-DEP-005</code>：非 resource 模块禁止 resource runtime；<code>MANGO-ARCH-DEP-006</code>：support 禁止依赖 core/starter；<code>MANGO-ARCH-DEP-007</code>：starter 只依赖本域实现和明确 infra starter；<code>MANGO-ARCH-DEP-008</code>：app 只依赖 Mango starter 与 mango-common。</li></ul><h3 id="_8-5-引擎-fail-closed-与执行边界" tabindex="-1">8.5 引擎 Fail-Closed 与执行边界 <a class="header-anchor" href="#_8-5-引擎-fail-closed-与执行边界" aria-label="Permalink to &quot;8.5 引擎 Fail-Closed 与执行边界&quot;">​</a></h3><ul><li><code>MANGO-ARCH-ENGINE-001</code>：Reactor 不可读；<code>MANGO-ARCH-ENGINE-002</code>：ArchUnit 导入失败；<code>MANGO-ARCH-ENGINE-003</code>：compiled classes 缺失/为空；<code>MANGO-ARCH-ENGINE-004</code>：class 无法映射 Reactor；<code>MANGO-ARCH-ENGINE-005</code>：Java source 缺失/不可扫描；<code>MANGO-ARCH-ENGINE-006</code>：PMD 失败；<code>MANGO-ARCH-ENGINE-007</code>：报告不可写；<code>MANGO-ARCH-ENGINE-008</code>：Git base 不可解析；<code>MANGO-ARCH-ENGINE-009</code>：module.properties 无效/冲突；<code>MANGO-ARCH-ENGINE-010</code>：PMD classpath 缺失；<code>MANGO-ARCH-ENGINE-011</code>：Reactor artifact 不完整；<code>MANGO-ARCH-ENGINE-012</code>：class 目录无法映射 artifact。</li><li><code>MANGO-ARCH-ENGINE-013</code>：禁止 excludedModules；<code>MANGO-ARCH-ENGINE-014</code>：全局 Entity manifest 缺失或合同/审批/期限无效；<code>MANGO-ARCH-ENGINE-015</code>：禁止 <code>mango.architecture.skip=true</code>；<code>MANGO-ARCH-ENGINE-016</code>：治理构建禁止 <code>requireFullReactor=false</code>；<code>MANGO-ARCH-ENGINE-017</code>：业务 Java 必须声明 package 且不得冒用 Mango/Spring/MyBatis/Jakarta 保留命名空间。</li><li>正式入口为 Reactor <code>mvn verify</code>。<code>mango:check</code> 同时固定 <code>rule=all</code>、<code>gate=all</code>、<code>staticFailurePolicy=block</code>、<code>changedOnly=false</code>、execution-root baseDir；<code>codeLevelExcludedModules</code>、缩小 rule/gate/baseDir 或把静态失败改为 report 都会阻断。</li><li><code>MODULE_INFO</code> 校验模块元数据；<code>PERSISTENCE_SCHEMA</code> 校验 migration、Entity 与 Mapper XML 表归属；聚合静态分析执行 PMD/P3C、Checkstyle、SpotBugs。</li><li>正例：完整生成项目执行 <code>mvn clean verify</code> 并产出 architecture/quality report。反例：只编译 core、changed-only 或排除模块后声明通过。</li><li>门禁只对上述静态事实承诺确定性。Require 不证明业务条件正确；Mapper/XML 不证明 SQL 业务语义；Controller/Feign parity 不替代权限、租户、异常和真实链路测试。任何失败不得由 Agent 自报、普通 baseline 或文档例外覆盖。</li></ul>',47)])])}const R=o(r,[["render",a]]);export{p as __pageData,R as default};
